file.content:
.counter {
  font-size: 16px;
  padding: 5px 10px;
  border-radius: 5px;
  color: var(--accent);
  background: var(--accent-bg);
  border: 2px solid transparent;
  transition: border-color 0.3s;
  margin-bottom: 24px;

  &:hover {
    border-color: var(--accent-border);
  }
  &:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

.hero {
  position: relative;

  .base,
  .framework,
  .vite {
    inset-inline: 0;
    margin: 0 auto;
  }

  .base {
    width: 170px;
    position: relative;
    z-index: 0;
  }

  .framework,
  .vite {
    position: absolute;
  }

  .framework {
    z-index: 1;
    top: 34px;
    height: 28px;
    transform: perspective(2000px) rotateZ(300deg) rotateX(44deg) rotateY(39deg)
      scale(1.4);
  }

  .vite {
    z-index: 0;
    top: 107px;
    height: 26px;
    width: auto;
    transform: perspective(2000px) rotateZ(300deg) rotateX(40deg) rotateY(39deg)
      scale(0.8);
  }
}

#center {
  display: flex;
  flex-direction: column;
  gap: 25px;
  place-content: center;
  place-items: center;
  flex-grow: 1;

  @media (max-width: 1024px) {
    padding: 32px 20px 24px;
    gap: 18px;
  }
}

#next-steps {
  display: flex;
  border-top: 1px solid var(--border);
  text-align: left;

  & > div {
    flex: 1 1 0;
    padding: 32px;
    @media (max-width: 1024px) {
      padding: 24px 20px;
    }
  }

  .icon {
    margin-bottom: 16px;
    width: 22px;
    height: 22px;
  }

  @media (max-width: 1024px) {
    flex-direction: column;
    text-align: center;
  }
}

#docs {
  border-right: 1px solid var(--border);

  @media (max-width: 1024px) {
    border-right: none;
    border-bottom: 1px solid var(--border);
  }
}

#next-steps ul {
  list-style: none;
  padding: 0;
  display: flex;
  gap: 8px;
  margin: 32px 0 0;

  .logo {
    height: 18px;
  }

  a {
    color: var(--text-h);
    font-size: 16px;
    border-radius: 6px;
    background: var(--social-bg);
    display: flex;
    padding: 6px 12px;
    align-items: center;
    gap: 8px;
    text-decoration: none;
    transition: box-shadow 0.3s;

    &:hover {
      box-shadow: var(--shadow);
    }
    .button-icon {
      height: 18px;
      width: 18px;
    }
  }

  @media (max-width: 1024px) {
    margin-top: 20px;
    flex-wrap: wrap;
    justify-content: center;

    li {
      flex: 1 1 calc(50% - 8px);
    }

    a {
      width: 100%;
      justify-content: center;
      box-sizing: border-box;
    }
  }
}

#spacer {
  height: 88px;
  border-top: 1px solid var(--border);
  @media (max-width: 1024px) {
    height: 48px;
  }
}

.ticks {
  position: relative;
  width: 100%;

  &::before,
  &::after {
    content: '';
    position: absolute;
    top: -4.5px;
    border: 5px solid transparent;
  }

  &::before {
    left: 0;
    border-left-color: var(--border);
  }
  &::after {
    right: 0;
    border-right-color: var(--border);
  }
}

input.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@300;400&family=Manrope:wght@300;400;500;600&family=Playfair+Display:ital,wght@0,500;0,600;1,500&display=swap');

:root {
  --ink: #071f2a;
  --deep: #062b3a;
  --blue: #07506b;
  --cream: #f3efe5;
  --paper: #e9e2d3;
  --coral: #ff657d;
  --gold: #f5a719;
  --mist: #d7e3e2;
  --serif: 'Playfair Display', 'Iowan Old Style', 'Baskerville', Georgia, serif;
  --sans: 'Manrope', 'Helvetica Neue', Arial, sans-serif;
  --mono: 'DM Mono', 'SFMono-Regular', Consolas, monospace;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  background: var(--ink);
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--ink);
  color: var(--cream);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body,
button,
a {
  cursor: default;
}

a,
button {
  color: inherit;
}

button {
  font: inherit;
}

button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--coral);
  outline-offset: 5px;
}

main {
  overflow: clip;
}

.intro-curtain {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1.25rem;
  background: var(--cream);
  color: var(--ink);
  transition: clip-path 1s cubic-bezier(.77, 0, .18, 1), visibility 1s;
  clip-path: inset(0 0 0 0);
}

.intro-curtain.is-gone {
  clip-path: inset(0 0 100% 0);
  visibility: hidden;
}

.intro-curtain p {
  margin: 0;
  font: 300 .62rem/1 var(--mono);
  letter-spacing: .24em;
  text-transform: uppercase;
}

.intro-word {
  display: flex;
  font: 500 clamp(3.5rem, 11vw, 10rem)/.7 var(--serif);
  letter-spacing: -.07em;
}

.intro-word span {
  opacity: 0;
  transform: translateY(45px) rotate(4deg);
  animation: intro-letter .6s cubic-bezier(.22, 1, .36, 1) forwards;
}

.intro-word span:nth-child(2) { animation-delay: .05s; }
.intro-word span:nth-child(3) { animation-delay: .1s; }
.intro-word span:nth-child(4) { animation-delay: .15s; }
.intro-word span:nth-child(5) { animation-delay: .2s; }
.intro-word span:nth-child(6) { animation-delay: .25s; }
.intro-word span:nth-child(7) { animation-delay: .3s; }

@keyframes intro-letter {
  to { opacity: 1; transform: translateY(0) rotate(0); }
}

.hero {
  --pointer-x: 73%;
  --pointer-y: 36%;
  position: relative;
  min-height: 100svh;
  isolation: isolate;
  background: var(--blue);
  overflow: hidden;
}

.hero-image,
.hero-shade,
.dream-lens,
.hero-title {
  position: absolute;
}

.hero-image {
  inset: -3%;
  z-index: -3;
  background-image: var(--botanical);
  background-position: center;
  background-size: cover;
  transform: scale(1.04);
  animation: hero-breathe 12s ease-in-out infinite alternate;
}

@keyframes hero-breathe {
  from { transform: scale(1.04); }
  to { transform: scale(1.095); }
}

.hero-shade {
  inset: 0;
  z-index: -2;
  background:
    linear-gradient(180deg, rgba(3, 28, 39, .32) 0%, transparent 30%, transparent 57%, rgba(2, 21, 28, .83) 100%),
    linear-gradient(90deg, rgba(2, 24, 31, .45), transparent 40%, rgba(2, 24, 31, .08));
}

.site-header {
  position: absolute;
  z-index: 15;
  top: 0;
  left: 0;
  right: 0;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  padding: 1.3rem 2rem;
  border-bottom: 1px solid rgba(243, 239, 229, .45);
}

.wordmark {
  width: fit-content;
  color: var(--cream);
  font: 500 1.6rem/1 var(--serif);
  letter-spacing: -.06em;
  text-decoration: none;
}

.edition {
  margin: 0;
  font: 300 .58rem/1 var(--mono);
  letter-spacing: .16em;
  text-transform: uppercase;
}

.menu-button {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: .8rem;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--cream);
  font: 400 .65rem/1 var(--mono);
  letter-spacing: .15em;
  text-transform: uppercase;
}

.menu-button i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 0 0 rgba(255, 101, 125, .65);
  animation: pulse 2.4s infinite;
}

@keyframes pulse {
  50% { box-shadow: 0 0 0 8px rgba(255, 101, 125, 0); }
}

.site-menu {
  position: absolute;
  z-index: 12;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: .1rem;
  padding-top: 3rem;
  background: rgba(4, 34, 45, .96);
  backdrop-filter: blur(18px);
  opacity: 0;
  visibility: hidden;
  transition: opacity .5s ease, visibility .5s;
}

.site-menu.is-open {
  opacity: 1;
  visibility: visible;
}

.site-menu a {
  position: relative;
  font: 500 clamp(2.7rem, 6.5vw, 6.5rem)/1.05 var(--serif);
  letter-spacing: -.055em;
  text-decoration: none;
  transform: translateY(1rem);
  transition: color .3s, transform .5s;
}

.site-menu.is-open a { transform: translateY(0); }
.site-menu a:hover { color: var(--coral); font-style: italic; }

.hero-title {
  z-index: 1;
  top: 45%;
  left: 1.3vw;
  right: 1.3vw;
  display: flex;
  justify-content: space-between;
  color: var(--cream);
  font: 500 clamp(7rem, 19vw, 20rem)/.7 var(--serif);
  letter-spacing: -.095em;
  text-shadow: 0 2px 25px rgba(1, 24, 32, .15);
  transform: translateY(-50%);
  pointer-events: none;
}

.hero-title span:last-child {
  margin-right: .06em;
}

.dream-lens {
  z-index: 2;
  top: var(--pointer-y);
  left: var(--pointer-x);
  width: clamp(10rem, 19vw, 19rem);
  aspect-ratio: 1;
  overflow: hidden;
  border: 1px solid rgba(243, 239, 229, .8);
  border-radius: 50% 48% 52% 45%;
  box-shadow: 0 25px 80px rgba(1, 22, 29, .32), inset 0 0 30px rgba(255,255,255,.1);
  transform: translate(-50%, -50%);
  transition: top .9s cubic-bezier(.22, 1, .36, 1), left .9s cubic-bezier(.22, 1, .36, 1);
  pointer-events: none;
}

.dream-lens-image {
  position: absolute;
  inset: -15%;
  background-image: var(--botanical);
  background-position: 68% 41%;
  background-size: 190%;
  filter: saturate(1.35) brightness(1.08);
  transform: scale(1.08) rotate(-4deg);
  animation: lens-drift 9s ease-in-out infinite alternate;
}

@keyframes lens-drift {
  to { transform: scale(1.18) rotate(3deg); background-position: 61% 46%; }
}

.dream-lens span {
  position: absolute;
  right: 1.2rem;
  bottom: 1.4rem;
  left: 1.2rem;
  padding-top: .7rem;
  border-top: 1px solid rgba(243, 239, 229, .65);
  color: white;
  font: 300 .53rem/1.4 var(--mono);
  letter-spacing: .13em;
  text-transform: uppercase;
}

.hero-copy {
  position: absolute;
  z-index: 4;
  left: 2rem;
  bottom: 2rem;
  width: min(38rem, 55vw);
}

.eyebrow {
  margin: 0 0 .9rem;
  font: 300 .6rem/1 var(--mono);
  letter-spacing: .18em;
  text-transform: uppercase;
}

.hero-copy h1 {
  max-width: 9em;
  margin: 0;
  color: var(--cream);
  font: 500 clamp(2.75rem, 5.4vw, 5.8rem)/.88 var(--serif);
  letter-spacing: -.062em;
}

.hero-cta {
  position: absolute;
  z-index: 5;
  right: 2rem;
  bottom: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: min(21rem, 26vw);
  padding: 1rem 0;
  border-top: 1px solid rgba(243, 239, 229, .7);
  border-bottom: 1px solid rgba(243, 239, 229, .7);
  font: 400 .65rem/1 var(--mono);
  letter-spacing: .14em;
  text-decoration: none;
  text-transform: uppercase;
  transition: padding .35s, color .35s;
}

.hero-cta:hover { padding-left: .7rem; padding-right: .7rem; color: #fff; }
.hero-cta svg,
.invitation-content a svg {
  width: 2.2rem;
  fill: none;
  stroke: currentColor;
  stroke-width: 1;
}

.hero-side-note {
  position: absolute;
  z-index: 4;
  top: 50%;
  right: -6.9rem;
  margin: 0;
  width: 17rem;
  font: 300 .52rem/1.5 var(--mono);
  letter-spacing: .12em;
  text-transform: uppercase;
  transform: rotate(90deg);
}

.manifesto {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 2.15fr 1fr;
  column-gap: 4vw;
  padding: clamp(5rem, 10vw, 10rem) 2rem clamp(6rem, 11vw, 12rem);
  background: var(--cream);
  color: var(--ink);
}

.manifesto-kicker {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  font: 300 .6rem/1.4 var(--mono);
  letter-spacing: .15em;
  text-transform: uppercase;
}

.manifesto-kicker span {
  display: grid;
  place-items: center;
  width: 2.1rem;
  height: 2.1rem;
  border: 1px solid var(--ink);
  border-radius: 50%;
}

.manifesto-kicker p { margin: .65rem 0 0; }
.manifesto-copy { grid-column: 2 / 3; }
.manifesto-lead {
  margin: 0 0 1.2rem;
  font: 300 .72rem/1 var(--mono);
  letter-spacing: .15em;
  text-transform: uppercase;
}

.manifesto-copy h2 {
  margin: 0;
  font: 500 clamp(3rem, 6.7vw, 7rem)/.98 var(--serif);
  letter-spacing: -.065em;
}

.manifesto-copy h2 em { color: var(--coral); font-weight: inherit; }
.manifesto-aside {
  align-self: end;
  max-width: 18rem;
  padding-bottom: .8rem;
}

.manifesto-aside > p:first-child {
  margin: 0;
  font-size: .86rem;
  font-weight: 300;
  line-height: 1.75;
}

.coordinates {
  margin: 3rem 0 0;
  padding-top: 1rem;
  border-top: 1px solid rgba(7, 31, 42, .35);
  font: 300 .57rem/1.7 var(--mono);
  letter-spacing: .12em;
}

.botanical-triptych {
  position: relative;
  grid-column: 1 / -1;
  height: clamp(32rem, 68vw, 65rem);
  margin-top: clamp(5rem, 11vw, 10rem);
}

.petal-frame {
  position: absolute;
  overflow: hidden;
  margin: 0;
  background: var(--blue);
}

.petal-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 1.2s cubic-bezier(.22, 1, .36, 1);
}

.petal-frame:hover img { transform: scale(1.06); }
.petal-one {
  top: 0;
  left: 18%;
  width: 47%;
  height: 67%;
  border-radius: 52% 48% 48% 52% / 62% 61% 39% 38%;
  transform: rotate(-5deg);
}

.petal-one img { object-position: 45% center; transform: scale(1.05) rotate(5deg); }
.petal-one:hover img { transform: scale(1.11) rotate(5deg); }
.petal-two {
  right: 5%;
  bottom: 1%;
  width: 37%;
  height: 57%;
  border-radius: 47% 53% 62% 38% / 36% 47% 53% 64%;
  transform: rotate(7deg);
}

.petal-two img { object-position: 82% center; transform: scale(1.12) rotate(-7deg); }
.petal-two:hover img { transform: scale(1.18) rotate(-7deg); }
.petal-three {
  left: 2%;
  bottom: 5%;
  width: 33%;
  height: 42%;
  border-radius: 45% 55% 45% 55% / 55% 40% 60% 45%;
  transform: rotate(-8deg);
}

.petal-three img { object-position: 57% 73%; transform: scale(1.2) rotate(8deg); filter: saturate(.7) contrast(1.13); }
.petal-three:hover img { transform: scale(1.26) rotate(8deg); }

.triptych-caption {
  position: absolute;
  right: 43%;
  bottom: 9%;
  width: 9rem;
  font: 300 .56rem/1.6 var(--mono);
  letter-spacing: .13em;
  text-transform: uppercase;
}

.notes-section {
  --note-accent: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1.25fr;
  min-height: 100svh;
  padding: clamp(5rem, 8vw, 8rem) 2rem 3rem;
  background: var(--ink);
  color: var(--cream);
  transition: background-color .7s ease;
}

.notes-section.tone-saffron { --note-accent: var(--gold); background: #13282b; }
.notes-section.tone-velvet { --note-accent: #9bb9b4; background: #052832; }

.notes-heading p {
  margin: 0 0 1.5rem;
  font: 300 .6rem/1 var(--mono);
  letter-spacing: .17em;
  text-transform: uppercase;
}

.notes-heading h2 {
  max-width: 8em;
  margin: 0;
  font: 500 clamp(3.5rem, 7vw, 7.5rem)/.93 var(--serif);
  letter-spacing: -.065em;
}

.scent-orbit {
  position: relative;
  align-self: center;
  justify-self: center;
  width: min(42vw, 38rem);
  aspect-ratio: 1;
}

.scent-image {
  position: absolute;
  inset: 16%;
  border-radius: 50%;
  background-size: 330%;
  box-shadow: 0 0 0 1px rgba(243,239,229,.2), 0 40px 100px rgba(0,0,0,.35);
  transition: background-position 1s cubic-bezier(.22, 1, .36, 1), filter .8s;
  animation: scent-pulse 6s ease-in-out infinite alternate;
}

@keyframes scent-pulse {
  to { transform: scale(1.035); }
}

.orbit-line {
  position: absolute;
  inset: 3%;
  border: 1px solid rgba(243,239,229,.28);
  border-radius: 50%;
  animation: orbit-spin 22s linear infinite;
}

.orbit-line::after {
  content: '';
  position: absolute;
  top: 11%;
  left: 11%;
  width: .65rem;
  height: .65rem;
  border-radius: 50%;
  background: var(--note-accent);
  box-shadow: 0 0 0 7px color-mix(in srgb, var(--note-accent) 14%, transparent);
}

.orbit-two {
  inset: 0 12%;
  transform: rotate(67deg);
  animation-duration: 31s;
  animation-direction: reverse;
}

.orbit-two::after { top: auto; bottom: 5%; left: 44%; width: .35rem; height: .35rem; }

@keyframes orbit-spin { to { transform: rotate(360deg); } }

.orbit-copy {
  position: absolute;
  right: -2rem;
  bottom: 12%;
  width: 10rem;
  margin: 0;
  padding-top: .7rem;
  border-top: 1px solid var(--note-accent);
  font-size: .72rem;
  font-weight: 300;
  line-height: 1.6;
}

.orbit-index {
  position: absolute;
  top: 13%;
  left: 5%;
  color: var(--note-accent);
  font: 500 2rem/1 var(--serif);
  font-style: italic;
}

.note-selector {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-self: end;
  gap: 1.5rem;
  margin-top: 4rem;
}

.note-selector button {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: .65rem;
  min-height: 8.5rem;
  padding: 1.2rem 0;
  border: 0;
  border-top: 1px solid rgba(243,239,229,.35);
  background: transparent;
  text-align: left;
  transition: border-color .35s;
}

.note-selector button span {
  font: 300 .55rem/1 var(--mono);
  letter-spacing: .13em;
  text-transform: uppercase;
}

.note-selector button strong {
  font: 500 clamp(1.6rem, 3vw, 3.2rem)/1 var(--serif);
  letter-spacing: -.04em;
}

.note-selector button i {
  position: absolute;
  right: 0;
  bottom: 1.25rem;
  left: 0;
  height: 2px;
  background: var(--note-accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .45s cubic-bezier(.22, 1, .36, 1);
}

.note-selector button.is-active { border-color: var(--note-accent); color: var(--note-accent); }
.note-selector button.is-active i { transform: scaleX(1); }
.note-selector button:hover strong { font-style: italic; }

.ritual {
  display: grid;
  grid-template-columns: 1.1fr .9fr;
  min-height: 100svh;
  background: var(--paper);
  color: var(--ink);
}

.ritual-image {
  position: relative;
  min-height: 45rem;
  overflow: hidden;
  background-position: 63% center;
  background-size: cover;
}

.ritual-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 60%, rgba(7,31,42,.12));
}

.ritual-marquee {
  position: absolute;
  z-index: 2;
  top: 50%;
  left: 0;
  display: flex;
  width: max-content;
  padding: .7rem 0 .8rem;
  background: var(--coral);
  color: var(--ink);
  font: 500 clamp(2rem, 4vw, 4rem)/1 var(--serif);
  letter-spacing: -.035em;
  transform: translateY(-50%) rotate(-8deg) translateX(-5%);
}

.ritual-marquee span {
  white-space: nowrap;
  animation: marquee 22s linear infinite;
}

@keyframes marquee { to { transform: translateX(-100%); } }

.ritual-content {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 3rem clamp(2rem, 5vw, 5rem);
}

.ritual-number {
  font: 300 .6rem/1 var(--mono);
  letter-spacing: .15em;
  text-transform: uppercase;
}

.ritual-content h2 {
  margin: auto 0 clamp(4rem, 8vw, 8rem);
  font: 500 clamp(3rem, 6.5vw, 6.9rem)/.94 var(--serif);
  letter-spacing: -.065em;
}

.ritual-content ol {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid rgba(7,31,42,.5);
}

.ritual-content li {
  display: grid;
  grid-template-columns: 6rem 1fr;
  gap: 2rem;
  padding: 1rem 0;
  border-bottom: 1px solid rgba(7,31,42,.3);
}

.ritual-content li span {
  font: 400 .58rem/1.6 var(--mono);
  letter-spacing: .15em;
  text-transform: uppercase;
}

.ritual-content li p { margin: 0; font-size: .82rem; font-weight: 300; line-height: 1.6; }

.invitation {
  position: relative;
  min-height: 100svh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--blue);
  overflow: hidden;
  isolation: isolate;
}

.invitation-image {
  position: absolute;
  inset: 0;
  z-index: -2;
  background-image: var(--botanical);
  background-position: center 38%;
  background-size: cover;
  filter: brightness(.58) saturate(1.15);
  transform: scale(1.08);
  transition: transform 2s cubic-bezier(.22, 1, .36, 1);
}

.invitation:hover .invitation-image { transform: scale(1.02); }
.invitation::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background: radial-gradient(circle at center, rgba(6,43,58,.18), rgba(1,20,27,.78));
}

.invitation-content {
  width: min(90%, 78rem);
  text-align: center;
}

.invitation-content > p {
  margin: 0 0 2rem;
  font: 300 .6rem/1 var(--mono);
  letter-spacing: .18em;
  text-transform: uppercase;
}

.invitation-content h2 {
  margin: 0;
  font: 500 clamp(5rem, 13vw, 13rem)/.68 var(--serif);
  letter-spacing: -.075em;
}

.invitation-content h2 em { color: var(--coral); font-weight: inherit; }
.invitation-content a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: min(100%, 29rem);
  margin: clamp(4rem, 8vw, 8rem) auto 0;
  padding: 1rem 0;
  border-top: 1px solid rgba(243,239,229,.65);
  border-bottom: 1px solid rgba(243,239,229,.65);
  font: 400 .62rem/1 var(--mono);
  letter-spacing: .14em;
  text-decoration: none;
  text-transform: uppercase;
  transition: color .35s, width .5s;
}

.invitation-content a:hover { color: var(--coral); width: min(100%, 32rem); }
.footer-meta {
  position: absolute;
  right: 2rem;
  bottom: 1.4rem;
  left: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font: 300 .5rem/1.4 var(--mono);
  letter-spacing: .12em;
  text-transform: uppercase;
}

.footer-meta a { text-decoration: none; }

[data-reveal] {
  opacity: 0;
  transform: translateY(2rem);
  transition: opacity .9s ease, transform 1s cubic-bezier(.22, 1, .36, 1);
}

[data-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}

@media (max-width: 900px) {
  .site-header { grid-template-columns: 1fr 1fr; padding: 1.1rem 1.2rem; }
  .edition { display: none; }
  .hero-title { top: 38%; font-size: 23vw; }
  .hero-copy { left: 1.2rem; bottom: 6.3rem; width: calc(100% - 2.4rem); }
  .hero-copy h1 { font-size: clamp(2.7rem, 11vw, 5.2rem); }
  .hero-cta { right: 1.2rem; bottom: 1.25rem; left: 1.2rem; width: auto; }
  .hero-side-note { display: none; }
  .dream-lens { width: 11.5rem; }

  .manifesto { grid-template-columns: 1fr; padding-inline: 1.2rem; }
  .manifesto-copy { grid-column: 1; margin-top: 4rem; }
  .manifesto-aside { margin: 3rem 0 0 auto; }
  .botanical-triptych { grid-column: 1; height: 38rem; margin-top: 5rem; }
  .petal-one { left: 10%; width: 66%; height: 58%; }
  .petal-two { right: -4%; width: 52%; height: 48%; }
  .petal-three { left: -6%; width: 46%; height: 37%; }
  .triptych-caption { right: 42%; bottom: 2%; }

  .notes-section { grid-template-columns: 1fr; padding-inline: 1.2rem; }
  .notes-heading h2 { font-size: clamp(3.4rem, 13vw, 6rem); }
  .scent-orbit { width: min(88vw, 34rem); margin: 3rem auto 1rem; }
  .orbit-copy { right: 0; }
  .note-selector { grid-template-columns: 1fr; gap: 0; margin-top: 3rem; }
  .note-selector button { min-height: auto; padding: 1.2rem 0 1.6rem; }
  .note-selector button i { bottom: .7rem; }

  .ritual { grid-template-columns: 1fr; }
  .ritual-image { min-height: 70svh; }
  .ritual-content { min-height: 90svh; padding: 2rem 1.2rem 3rem; }
  .ritual-content h2 { margin-top: 7rem; }

  .footer-meta { right: 1.2rem; bottom: 1rem; left: 1.2rem; }
  .footer-meta span:nth-child(2) { display: none; }
}

@media (max-width: 520px) {
  .hero-image { background-position: 48% center; }
  .hero-shade { background: linear-gradient(180deg, rgba(2,24,31,.35), transparent 42%, rgba(2,21,28,.88) 100%); }
  .hero-title { top: 35%; left: .55rem; right: .55rem; font-size: 22.5vw; }
  .dream-lens { top: 42%; left: 66%; width: 9rem; }
  .dream-lens span { display: none; }
  .hero-copy { bottom: 6.4rem; }
  .hero-copy h1 { max-width: 7.4em; line-height: .92; }
  .site-menu a { font-size: 2.65rem; }

  .manifesto-copy h2 { font-size: 3.15rem; }
  .manifesto-aside { max-width: 15rem; }
  .botanical-triptych { height: 31rem; }
  .petal-one { left: 4%; width: 75%; height: 55%; }
  .petal-two { width: 58%; height: 47%; }
  .petal-three { width: 51%; height: 34%; }
  .triptych-caption { right: 34%; bottom: -2%; width: 8rem; }

  .notes-section { min-height: auto; }
  .notes-heading h2 { font-size: 3.5rem; }
  .orbit-copy { bottom: 3%; width: 8rem; background: rgba(7,31,42,.72); padding: .7rem; }
  .scent-image { inset: 18%; }
  .note-selector button strong { font-size: 2rem; }

  .ritual-image { min-height: 60svh; background-position: 57% center; }
  .ritual-content { min-height: 80svh; }
  .ritual-content h2 { font-size: 3.6rem; }
  .ritual-content li { grid-template-columns: 4.5rem 1fr; gap: 1rem; }

  .invitation-content h2 { font-size: 19vw; line-height: .75; }
  .invitation-content > p { line-height: 1.7; }
  .invitation-content a { font-size: .56rem; }
  .footer-meta { font-size: .45rem; }
}

@media (hover: hover) and (pointer: fine) {
  a,
  button { cursor: pointer; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *,
  *::before,
  *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
  .intro-curtain { display: none; }
}

tool_use_result.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@300;400&family=Manrope:wght@300;400;500;600&family=Playfair+Display:ital,wght@0,500;0,600;1,500&display=swap');

:root {
  --ink: #071f2a;
  --deep: #062b3a;
  --blue: #07506b;
  --cream: #f3efe5;
  --paper: #e9e2d3;
  --coral: #ff657d;
  --gold: #f5a719;
  --mist: #d7e3e2;
  --serif: 'Playfair Display', 'Iowan Old Style', 'Baskerville', Georgia, serif;
  --sans: 'Manrope', 'Helvetica Neue', Arial, sans-serif;
  --mono: 'DM Mono', 'SFMono-Regular', Consolas, monospace;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  background: var(--ink);
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--ink);
  color: var(--cream);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body,
button,
a {
  cursor: default;
}

a,
button {
  color: inherit;
}

button {
  font: inherit;
}

button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--coral);
  outline-offset: 5px;
}

main {
  overflow: clip;
}

.intro-curtain {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1.25rem;
  background: var(--cream);
  color: var(--ink);
  transition: clip-path 1s cubic-bezier(.77, 0, .18, 1), visibility 1s;
  clip-path: inset(0 0 0 0);
}

.intro-curtain.is-gone {
  clip-path: inset(0 0 100% 0);
  visibility: hidden;
}

.intro-curtain p {
  margin: 0;
  font: 300 .62rem/1 var(--mono);
  letter-spacing: .24em;
  text-transform: uppercase;
}

.intro-word {
  display: flex;
  font: 500 clamp(3.5rem, 11vw, 10rem)/.7 var(--serif);
  letter-spacing: -.07em;
}

.intro-word span {
  opacity: 0;
  transform: translateY(45px) rotate(4deg);
  animation: intro-letter .6s cubic-bezier(.22, 1, .36, 1) forwards;
}

.intro-word span:nth-child(2) { animation-delay: .05s; }
.intro-word span:nth-child(3) { animation-delay: .1s; }
.intro-word span:nth-child(4) { animation-delay: .15s; }
.intro-word span:nth-child(5) { animation-delay: .2s; }
.intro-word span:nth-child(6) { animation-delay: .25s; }
.intro-word span:nth-child(7) { animation-delay: .3s; }

@keyframes intro-letter {
  to { opacity: 1; transform: translateY(0) rotate(0); }
}

.hero {
  --pointer-x: 73%;
  --pointer-y: 36%;
  position: relative;
  min-height: 100svh;
  isolation: isolate;
  background: var(--blue);
  overflow: hidden;
}

.hero-image,
.hero-shade,
.dream-lens,
.hero-title {
  position: absolute;
}

.hero-image {
  inset: -3%;
  z-index: -3;
  background-image: var(--botanical);
  background-position: center;
  background-size: cover;
  transform: scale(1.04);
  animation: hero-breathe 12s ease-in-out infinite alternate;
}

@keyframes hero-breathe {
  from { transform: scale(1.04); }
  to { transform: scale(1.095); }
}

.hero-shade {
  inset: 0;
  z-index: -2;
  background:
    linear-gradient(180deg, rgba(3, 28, 39, .32) 0%, transparent 30%, transparent 57%, rgba(2, 21, 28, .83) 100%),
    linear-gradient(90deg, rgba(2, 24, 31, .45), transparent 40%, rgba(2, 24, 31, .08));
}

.site-header {
  position: absolute;
  z-index: 15;
  top: 0;
  left: 0;
  right: 0;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  padding: 1.3rem 2rem;
  border-bottom: 1px solid rgba(243, 239, 229, .45);
}

.wordmark {
  width: fit-content;
  color: var(--cream);
  font: 500 1.6rem/1 var(--serif);
  letter-spacing: -.06em;
  text-decoration: none;
}

.edition {
  margin: 0;
  font: 300 .58rem/1 var(--mono);
  letter-spacing: .16em;
  text-transform: uppercase;
}

.menu-button {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: .8rem;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--cream);
  font: 400 .65rem/1 var(--mono);
  letter-spacing: .15em;
  text-transform: uppercase;
}

.menu-button i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 0 0 rgba(255, 101, 125, .65);
  animation: pulse 2.4s infinite;
}

@keyframes pulse {
  50% { box-shadow: 0 0 0 8px rgba(255, 101, 125, 0); }
}

.site-menu {
  position: absolute;
  z-index: 12;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: .1rem;
  padding-top: 3rem;
  background: rgba(4, 34, 45, .96);
  backdrop-filter: blur(18px);
  opacity: 0;
  visibility: hidden;
  transition: opacity .5s ease, visibility .5s;
}

.site-menu.is-open {
  opacity: 1;
  visibility: visible;
}

.site-menu a {
  position: relative;
  font: 500 clamp(2.7rem, 6.5vw, 6.5rem)/1.05 var(--serif);
  letter-spacing: -.055em;
  text-decoration: none;
  transform: translateY(1rem);
  transition: color .3s, transform .5s;
}

.site-menu.is-open a { transform: translateY(0); }
.site-menu a:hover { color: var(--coral); font-style: italic; }

.hero-title {
  z-index: 1;
  top: 45%;
  left: 1.3vw;
  right: 1.3vw;
  display: flex;
  justify-content: space-between;
  color: var(--cream);
  font: 500 clamp(7rem, 19vw, 20rem)/.7 var(--serif);
  letter-spacing: -.095em;
  text-shadow: 0 2px 25px rgba(1, 24, 32, .15);
  transform: translateY(-50%);
  pointer-events: none;
}

.hero-title span:last-child {
  margin-right: .06em;
}

.dream-lens {
  z-index: 2;
  top: var(--pointer-y);
  left: var(--pointer-x);
  width: clamp(10rem, 19vw, 19rem);
  aspect-ratio: 1;
  overflow: hidden;
  border: 1px solid rgba(243, 239, 229, .8);
  border-radius: 50% 48% 52% 45%;
  box-shadow: 0 25px 80px rgba(1, 22, 29, .32), inset 0 0 30px rgba(255,255,255,.1);
  transform: translate(-50%, -50%);
  transition: top .9s cubic-bezier(.22, 1, .36, 1), left .9s cubic-bezier(.22, 1, .36, 1);
  pointer-events: none;
}

.dream-lens-image {
  position: absolute;
  inset: -15%;
  background-image: var(--botanical);
  background-position: 68% 41%;
  background-size: 190%;
  filter: saturate(1.35) brightness(1.08);
  transform: scale(1.08) rotate(-4deg);
  animation: lens-drift 9s ease-in-out infinite alternate;
}

@keyframes lens-drift {
  to { transform: scale(1.18) rotate(3deg); background-position: 61% 46%; }
}

.dream-lens span {
  position: absolute;
  right: 1.2rem;
  bottom: 1.4rem;
  left: 1.2rem;
  padding-top: .7rem;
  border-top: 1px solid rgba(243, 239, 229, .65);
  color: white;
  font: 300 .53rem/1.4 var(--mono);
  letter-spacing: .13em;
  text-transform: uppercase;
}

.hero-copy {
  position: absolute;
  z-index: 4;
  left: 2rem;
  bottom: 2rem;
  width: min(38rem, 55vw);
}

.eyebrow {
  margin: 0 0 .9rem;
  font: 300 .6rem/1 var(--mono);
  letter-spacing: .18em;
  text-transform: uppercase;
}

.hero-copy h1 {
  max-width: 9em;
  margin: 0;
  color: var(--cream);
  font: 500 clamp(2.75rem, 5.4vw, 5.8rem)/.88 var(--serif);
  letter-spacing: -.062em;
}

.hero-cta {
  position: absolute;
  z-index: 5;
  right: 2rem;
  bottom: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: min(21rem, 26vw);
  padding: 1rem 0;
  border-top: 1px solid rgba(243, 239, 229, .7);
  border-bottom: 1px solid rgba(243, 239, 229, .7);
  font: 400 .65rem/1 var(--mono);
  letter-spacing: .14em;
  text-decoration: none;
  text-transform: uppercase;
  transition: padding .35s, color .35s;
}

.hero-cta:hover { padding-left: .7rem; padding-right: .7rem; color: #fff; }
.hero-cta svg,
.invitation-content a svg {
  width: 2.2rem;
  fill: none;
  stroke: currentColor;
  stroke-width: 1;
}

.hero-side-note {
  position: absolute;
  z-index: 4;
  top: 50%;
  right: -6.9rem;
  margin: 0;
  width: 17rem;
  font: 300 .52rem/1.5 var(--mono);
  letter-spacing: .12em;
  text-transform: uppercase;
  transform: rotate(90deg);
}

.manifesto {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 2.15fr 1fr;
  column-gap: 4vw;
  padding: clamp(5rem, 10vw, 10rem) 2rem clamp(6rem, 11vw, 12rem);
  background: var(--cream);
  color: var(--ink);
}

.manifesto-kicker {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  font: 300 .6rem/1.4 var(--mono);
  letter-spacing: .15em;
  text-transform: uppercase;
}

.manifesto-kicker span {
  display: grid;
  place-items: center;
  width: 2.1rem;
  height: 2.1rem;
  border: 1px solid var(--ink);
  border-radius: 50%;
}

.manifesto-kicker p { margin: .65rem 0 0; }
.manifesto-copy { grid-column: 2 / 3; }
.manifesto-lead {
  margin: 0 0 1.2rem;
  font: 300 .72rem/1 var(--mono);
  letter-spacing: .15em;
  text-transform: uppercase;
}

.manifesto-copy h2 {
  margin: 0;
  font: 500 clamp(3rem, 6.7vw, 7rem)/.98 var(--serif);
  letter-spacing: -.065em;
}

.manifesto-copy h2 em { color: var(--coral); font-weight: inherit; }
.manifesto-aside {
  align-self: end;
  max-width: 18rem;
  padding-bottom: .8rem;
}

.manifesto-aside > p:first-child {
  margin: 0;
  font-size: .86rem;
  font-weight: 300;
  line-height: 1.75;
}

.coordinates {
  margin: 3rem 0 0;
  padding-top: 1rem;
  border-top: 1px solid rgba(7, 31, 42, .35);
  font: 300 .57rem/1.7 var(--mono);
  letter-spacing: .12em;
}

.botanical-triptych {
  position: relative;
  grid-column: 1 / -1;
  height: clamp(32rem, 68vw, 65rem);
  margin-top: clamp(5rem, 11vw, 10rem);
}

.petal-frame {
  position: absolute;
  overflow: hidden;
  margin: 0;
  background: var(--blue);
}

.petal-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 1.2s cubic-bezier(.22, 1, .36, 1);
}

.petal-frame:hover img { transform: scale(1.06); }
.petal-one {
  top: 0;
  left: 18%;
  width: 47%;
  height: 67%;
  border-radius: 52% 48% 48% 52% / 62% 61% 39% 38%;
  transform: rotate(-5deg);
}

.petal-one img { object-position: 45% center; transform: scale(1.05) rotate(5deg); }
.petal-one:hover img { transform: scale(1.11) rotate(5deg); }
.petal-two {
  right: 5%;
  bottom: 1%;
  width: 37%;
  height: 57%;
  border-radius: 47% 53% 62% 38% / 36% 47% 53% 64%;
  transform: rotate(7deg);
}

.petal-two img { object-position: 82% center; transform: scale(1.12) rotate(-7deg); }
.petal-two:hover img { transform: scale(1.18) rotate(-7deg); }
.petal-three {
  left: 2%;
  bottom: 5%;
  width: 33%;
  height: 42%;
  border-radius: 45% 55% 45% 55% / 55% 40% 60% 45%;
  transform: rotate(-8deg);
}

.petal-three img { object-position: 57% 73%; transform: scale(1.2) rotate(8deg); filter: saturate(.7) contrast(1.13); }
.petal-three:hover img { transform: scale(1.26) rotate(8deg); }

.triptych-caption {
  position: absolute;
  right: 43%;
  bottom: 9%;
  width: 9rem;
  font: 300 .56rem/1.6 var(--mono);
  letter-spacing: .13em;
  text-transform: uppercase;
}

.notes-section {
  --note-accent: var(--coral);
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1.25fr;
  min-height: 100svh;
  padding: clamp(5rem, 8vw, 8rem) 2rem 3rem;
  background: var(--ink);
  color: var(--cream);
  transition: background-color .7s ease;
}

.notes-section.tone-saffron { --note-accent: var(--gold); background: #13282b; }
.notes-section.tone-velvet { --note-accent: #9bb9b4; background: #052832; }

.notes-heading p {
  margin: 0 0 1.5rem;
  font: 300 .6rem/1 var(--mono);
  letter-spacing: .17em;
  text-transform: uppercase;
}

.notes-heading h2 {
  max-width: 8em;
  margin: 0;
  font: 500 clamp(3.5rem, 7vw, 7.5rem)/.93 var(--serif);
  letter-spacing: -.065em;
}

.scent-orbit {
  position: relative;
  align-self: center;
  justify-self: center;
  width: min(42vw, 38rem);
  aspect-ratio: 1;
}

.scent-image {
  position: absolute;
  inset: 16%;
  border-radius: 50%;
  background-size: 330%;
  box-shadow: 0 0 0 1px rgba(243,239,229,.2), 0 40px 100px rgba(0,0,0,.35);
  transition: background-position 1s cubic-bezier(.22, 1, .36, 1), filter .8s;
  animation: scent-pulse 6s ease-in-out infinite alternate;
}

@keyframes scent-pulse {
  to { transform: scale(1.035); }
}

.orbit-line {
  position: absolute;
  inset: 3%;
  border: 1px solid rgba(243,239,229,.28);
  border-radius: 50%;
  animation: orbit-spin 22s linear infinite;
}

.orbit-line::after {
  content: '';
  position: absolute;
  top: 11%;
  left: 11%;
  width: .65rem;
  height: .65rem;
  border-radius: 50%;
  background: var(--note-accent);
  box-shadow: 0 0 0 7px color-mix(in srgb, var(--note-accent) 14%, transparent);
}

.orbit-two {
  inset: 0 12%;
  transform: rotate(67deg);
  animation-duration: 31s;
  animation-direction: reverse;
}

.orbit-two::after { top: auto; bottom: 5%; left: 44%; width: .35rem; height: .35rem; }

@keyframes orbit-spin { to { transform: rotate(360deg); } }

.orbit-copy {
  position: absolute;
  right: -2rem;
  bottom: 12%;
  width: 10rem;
  margin: 0;
  padding-top: .7rem;
  border-top: 1px solid var(--note-accent);
  font-size: .72rem;
  font-weight: 300;
  line-height: 1.6;
}

.orbit-index {
  position: absolute;
  top: 13%;
  left: 5%;
  color: var(--note-accent);
  font: 500 2rem/1 var(--serif);
  font-style: italic;
}

.note-selector {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-self: end;
  gap: 1.5rem;
  margin-top: 4rem;
}

.note-selector button {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: .65rem;
  min-height: 8.5rem;
  padding: 1.2rem 0;
  border: 0;
  border-top: 1px solid rgba(243,239,229,.35);
  background: transparent;
  text-align: left;
  transition: border-color .35s;
}

.note-selector button span {
  font: 300 .55rem/1 var(--mono);
  letter-spacing: .13em;
  text-transform: uppercase;
}

.note-selector button strong {
  font: 500 clamp(1.6rem, 3vw, 3.2rem)/1 var(--serif);
  letter-spacing: -.04em;
}

.note-selector button i {
  position: absolute;
  right: 0;
  bottom: 1.25rem;
  left: 0;
  height: 2px;
  background: var(--note-accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .45s cubic-bezier(.22, 1, .36, 1);
}

.note-selector button.is-active { border-color: var(--note-accent); color: var(--note-accent); }
.note-selector button.is-active i { transform: scaleX(1); }
.note-selector button:hover strong { font-style: italic; }

.ritual {
  display: grid;
  grid-template-columns: 1.1fr .9fr;
  min-height: 100svh;
  background: var(--paper);
  color: var(--ink);
}

.ritual-image {
  position: relative;
  min-height: 45rem;
  overflow: hidden;
  background-position: 63% center;
  background-size: cover;
}

.ritual-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 60%, rgba(7,31,42,.12));
}

.ritual-marquee {
  position: absolute;
  z-index: 2;
  top: 50%;
  left: 0;
  display: flex;
  width: max-content;
  padding: .7rem 0 .8rem;
  background: var(--coral);
  color: var(--ink);
  font: 500 clamp(2rem, 4vw, 4rem)/1 var(--serif);
  letter-spacing: -.035em;
  transform: translateY(-50%) rotate(-8deg) translateX(-5%);
}

.ritual-marquee span {
  white-space: nowrap;
  animation: marquee 22s linear infinite;
}

@keyframes marquee { to { transform: translateX(-100%); } }

.ritual-content {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 3rem clamp(2rem, 5vw, 5rem);
}

.ritual-number {
  font: 300 .6rem/1 var(--mono);
  letter-spacing: .15em;
  text-transform: uppercase;
}

.ritual-content h2 {
  margin: auto 0 clamp(4rem, 8vw, 8rem);
  font: 500 clamp(3rem, 6.5vw, 6.9rem)/.94 var(--serif);
  letter-spacing: -.065em;
}

.ritual-content ol {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid rgba(7,31,42,.5);
}

.ritual-content li {
  display: grid;
  grid-template-columns: 6rem 1fr;
  gap: 2rem;
  padding: 1rem 0;
  border-bottom: 1px solid rgba(7,31,42,.3);
}

.ritual-content li span {
  font: 400 .58rem/1.6 var(--mono);
  letter-spacing: .15em;
  text-transform: uppercase;
}

.ritual-content li p { margin: 0; font-size: .82rem; font-weight: 300; line-height: 1.6; }

.invitation {
  position: relative;
  min-height: 100svh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--blue);
  overflow: hidden;
  isolation: isolate;
}

.invitation-image {
  position: absolute;
  inset: 0;
  z-index: -2;
  background-image: var(--botanical);
  background-position: center 38%;
  background-size: cover;
  filter: brightness(.58) saturate(1.15);
  transform: scale(1.08);
  transition: transform 2s cubic-bezier(.22, 1, .36, 1);
}

.invitation:hover .invitation-image { transform: scale(1.02); }
.invitation::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background: radial-gradient(circle at center, rgba(6,43,58,.18), rgba(1,20,27,.78));
}

.invitation-content {
  width: min(90%, 78rem);
  text-align: center;
}

.invitation-content > p {
  margin: 0 0 2rem;
  font: 300 .6rem/1 var(--mono);
  letter-spacing: .18em;
  text-transform: uppercase;
}

.invitation-content h2 {
  margin: 0;
  font: 500 clamp(5rem, 13vw, 13rem)/.68 var(--serif);
  letter-spacing: -.075em;
}

.invitation-content h2 em { color: var(--coral); font-weight: inherit; }
.invitation-content a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: min(100%, 29rem);
  margin: clamp(4rem, 8vw, 8rem) auto 0;
  padding: 1rem 0;
  border-top: 1px solid rgba(243,239,229,.65);
  border-bottom: 1px solid rgba(243,239,229,.65);
  font: 400 .62rem/1 var(--mono);
  letter-spacing: .14em;
  text-decoration: none;
  text-transform: uppercase;
  transition: color .35s, width .5s;
}

.invitation-content a:hover { color: var(--coral); width: min(100%, 32rem); }
.footer-meta {
  position: absolute;
  right: 2rem;
  bottom: 1.4rem;
  left: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font: 300 .5rem/1.4 var(--mono);
  letter-spacing: .12em;
  text-transform: uppercase;
}

.footer-meta a { text-decoration: none; }

[data-reveal] {
  opacity: 0;
  transform: translateY(2rem);
  transition: opacity .9s ease, transform 1s cubic-bezier(.22, 1, .36, 1);
}

[data-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}

@media (max-width: 900px) {
  .site-header { grid-template-columns: 1fr 1fr; padding: 1.1rem 1.2rem; }
  .edition { display: none; }
  .hero-title { top: 38%; font-size: 23vw; }
  .hero-copy { left: 1.2rem; bottom: 6.3rem; width: calc(100% - 2.4rem); }
  .hero-copy h1 { font-size: clamp(2.7rem, 11vw, 5.2rem); }
  .hero-cta { right: 1.2rem; bottom: 1.25rem; left: 1.2rem; width: auto; }
  .hero-side-note { display: none; }
  .dream-lens { width: 11.5rem; }

  .manifesto { grid-template-columns: 1fr; padding-inline: 1.2rem; }
  .manifesto-copy { grid-column: 1; margin-top: 4rem; }
  .manifesto-aside { margin: 3rem 0 0 auto; }
  .botanical-triptych { grid-column: 1; height: 38rem; margin-top: 5rem; }
  .petal-one { left: 10%; width: 66%; height: 58%; }
  .petal-two { right: -4%; width: 52%; height: 48%; }
  .petal-three { left: -6%; width: 46%; height: 37%; }
  .triptych-caption { right: 42%; bottom: 2%; }

  .notes-section { grid-template-columns: 1fr; padding-inline: 1.2rem; }
  .notes-heading h2 { font-size: clamp(3.4rem, 13vw, 6rem); }
  .scent-orbit { width: min(88vw, 34rem); margin: 3rem auto 1rem; }
  .orbit-copy { right: 0; }
  .note-selector { grid-template-columns: 1fr; gap: 0; margin-top: 3rem; }
  .note-selector button { min-height: auto; padding: 1.2rem 0 1.6rem; }
  .note-selector button i { bottom: .7rem; }

  .ritual { grid-template-columns: 1fr; }
  .ritual-image { min-height: 70svh; }
  .ritual-content { min-height: 90svh; padding: 2rem 1.2rem 3rem; }
  .ritual-content h2 { margin-top: 7rem; }

  .footer-meta { right: 1.2rem; bottom: 1rem; left: 1.2rem; }
  .footer-meta span:nth-child(2) { display: none; }
}

@media (max-width: 520px) {
  .hero-image { background-position: 48% center; }
  .hero-shade { background: linear-gradient(180deg, rgba(2,24,31,.35), transparent 42%, rgba(2,21,28,.88) 100%); }
  .hero-title { top: 35%; left: .55rem; right: .55rem; font-size: 22.5vw; }
  .dream-lens { top: 42%; left: 66%; width: 9rem; }
  .dream-lens span { display: none; }
  .hero-copy { bottom: 6.4rem; }
  .hero-copy h1 { max-width: 7.4em; line-height: .92; }
  .site-menu a { font-size: 2.65rem; }

  .manifesto-copy h2 { font-size: 3.15rem; }
  .manifesto-aside { max-width: 15rem; }
  .botanical-triptych { height: 31rem; }
  .petal-one { left: 4%; width: 75%; height: 55%; }
  .petal-two { width: 58%; height: 47%; }
  .petal-three { width: 51%; height: 34%; }
  .triptych-caption { right: 34%; bottom: -2%; width: 8rem; }

  .notes-section { min-height: auto; }
  .notes-heading h2 { font-size: 3.5rem; }
  .orbit-copy { bottom: 3%; width: 8rem; background: rgba(7,31,42,.72); padding: .7rem; }
  .scent-image { inset: 18%; }
  .note-selector button strong { font-size: 2rem; }

  .ritual-image { min-height: 60svh; background-position: 57% center; }
  .ritual-content { min-height: 80svh; }
  .ritual-content h2 { font-size: 3.6rem; }
  .ritual-content li { grid-template-columns: 4.5rem 1fr; gap: 1rem; }

  .invitation-content h2 { font-size: 19vw; line-height: .75; }
  .invitation-content > p { line-height: 1.7; }
  .invitation-content a { font-size: .56rem; }
  .footer-meta { font-size: .45rem; }
}

@media (hover: hover) and (pointer: fine) {
  a,
  button { cursor: pointer; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *,
  *::before,
  *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
  .intro-curtain { display: none; }
}

