const page = await browser.getPage("elysian-errors");
const errors = [];
page.on("console", (message) => { if (message.type() === "error") errors.push(`console: ${message.text()}`); });
page.on("pageerror", (error) => errors.push(`pageerror: ${error.message}`));
await page.setViewportSize({ width: 1280, height: 800 });
await page.goto("http://127.0.0.1:4173");
await page.waitForTimeout(3200);
await page.getByRole("button", { name: "Menu" }).click();
await page.waitForTimeout(200);
await page.getByRole("button", { name: "Close" }).click();
await page.evaluate(() => document.getElementById("notes")?.scrollIntoView());
await page.waitForTimeout(700);
for (const name of [/Saffron smoke/, /Velvet leaf/, /Night jasmine/]) await page.getByRole("tab", { name }).click();
await page.waitForTimeout(500);
console.log(JSON.stringify({ errors, finalSelected: await page.getByRole("tab", { name: /Night jasmine/ }).getAttribute("aria-selected") }, null, 2));
EOF

